SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(480, 270, "#bfe6f2");
  SZGame2D.setStageDescription("Leve os doces do Bento pela rua: pule as pedras com Espaço, com a seta para cima ou com um toque na tela.");
  const entregador = SZGame2D.createDino({ x: 70, y: 150, size: 56, color: "#f2a65a" });
  const pedras = SZGame2D.createGroup();
  SZGame2D.setScene("inicio");
  SZGame2D.setHitboxScale(entregador, 80);
  let metros = 0;
  let velocidade = -5;
  // Quando acontecer
  SZGame2D.onAnyInput(() => {
      if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.setScene("jogando");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.restart();
    }
    }, "vila_pulo_events_0");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "vila");
    if (SZGame2D.sceneIs("jogando")) {
      SZGame2D.drawSprite(ctx, entregador);
      SZGame2D.updateGroup(pedras);
      SZGame2D.drawGroup(ctx, pedras);
      SZGame2D.overlapSpriteGroup(() => entregador, pedras, (pedra) => {
        SZGame2D.explodeSprite(pedra, "#f2b56a");
        SZGame2D.shake(ctx, 6);
        SZGame2D.playFx("gameover");
        SZGame2D.setScene("fim");
      });
      SZGame2D.pruneOffscreen(ctx, pedras, 40, (pedra) => {

      });
      SZGame2D.drawScore(ctx, "Metros: ", metros, 12, 30, "#493c56", 22);
    } else if (SZGame2D.sceneIs("inicio")) {
      SZGame2D.showScreen(ctx, "A corrida do entregador", "Leve os doces do Bento pela rua.", "Aperte uma tecla ou toque na tela para começar", "#5b3a2e");
    } else if (SZGame2D.sceneIs("fim")) {
      SZGame2D.showScreen(ctx, "Fim da corrida", "Uma pedra derrubou o entregador.", "Aperte uma tecla ou toque para correr de novo", "#5b3a2e");
      SZGame2D.drawScore(ctx, "Metros: ", metros, 190, 240, "#fff4d8", 22);
    }
  }, "vila_pulo_loops_0");
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everySeconds("cada", 1.4)) {
      if (SZGame2D.sceneIs("jogando")) {
        SZGame2D.spawnObstacle(pedras, ctx, { type: "rock", x: SZGame2D.randomBetween(500, 560), size: SZGame2D.randomBetween(28, 44), vx: velocidade });
        if (velocidade > -9) {
          velocidade = velocidade - 1;
        }
      }
    }
  });
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everySeconds("cada_2", 1)) {
      if (SZGame2D.sceneIs("jogando")) {
        metros = metros + 1;
      }
    }
  });
}, "__sz-project");

